package com.example.namaz.asistani; import android.app.PendingIntent; import android.appwidget.AppWidgetManager; import android.content.Context; import android.content.Intent; import android.widget.RemoteViews; public class AppWidgetProvider extends android.appwidget.AppWidgetProvider { @Override public void onUpdate(Context context, AppWidgetManager manager, int[] ids) { Intent launch = context.getPackageManager().getLaunchIntentForPackage(context.getPackageName()); if (launch == null) return; PendingIntent pending = PendingIntent.getActivity(context, 0, launch, PendingIntent.FLAG_UPDATE_CURRENT | PendingIntent.FLAG_IMMUTABLE); for (int id : ids) { RemoteViews views = new RemoteViews(context.getPackageName(), R.layout.widget_layout); views.setTextViewText(R.id.widget_title, context.getSharedPreferences("widget_prayer", Context.MODE_PRIVATE).getString("status", context.getString(R.string.app_name))); views.setOnClickPendingIntent(R.id.widget_title, pending); manager.updateAppWidget(id, views); } } }